Definition RELm (st : mstate) (mem : aptr -> Prop) (a : mstate) : Prop :=
  forall x, MR a x = MR st x \/ (mem x /\ GEOM (MR a x) = GEOM (MR st x) /\ fsub (fmask (MR a x)) (fmask (MR st x))).

